}

.hud-quick-camera__btn--c1.is-active {
  /* 1.85rem → 150% */
  min-width: 2.775rem;
  height: 2.775rem;
  padding-bottom: 0.18rem;
}

.hud-quick-camera__num {
  line-height: 1;
}

.hud-quick-camera__c1-mark {
  margin-top: 0.12rem;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.02em;
  color: #2563EB;
  line-height: 1;
}

.hud-quick-camera__btn.is-active {
  border-color: #2563EB;
  background: #2563EB;
  color: #FFFFFF;
}

.hud-quick-camera__btn:focus-visible {
  outline: 2px solid #2563EB;
  outline-offset: 1px;
}

@media (max-height: 420px) {
  .hud-quick-camera__btn {
    /* 1.35rem → 150% */
    min-width: 2.025rem;
    height: 2.025rem;
    font-size: 0.975rem;
  }

  .hud-quick-camera__btn--c1.is-active {
    /* 1.55rem → 150% */
    min-width: 2.325rem;
    height: 2.325rem;
  }

  .hud-quick-camera__c1-mark {
    font-size: 0.63rem;
  }

  .hud-ride-map-controls__style,
  .hud-ride-map-controls__zoom {
    min-width: 2.025rem;
    height: 2.025rem;
  }

  .hud-ride-map-controls__zoom {
    font-size: 0.975rem;
  }
}

/*
 * 지시 06-2 — 폰 가로+좁은 폭에서 우상단 [QC][야외−+][계정] 이 좌상단 계기판(새 도로)을 덮는다.
 * 해법 a: 한 줄 유지, 카메라·맵 버튼의 시각 폭만 축소. 터치 44px 는 ::after.
 */
@media (max-width: 900px) and (max-height: 560px) {
  .map-hud__tr {
    gap: 0.2rem;
  }

  .hud-quick-camera {
    gap: 0.1rem;
  }

  .hud-quick-camera__btn {
    min-width: 1.55rem;
    height: 1.55rem;
    padding: 0 0.22rem;
    font-size: 0.85rem;
    border-radius: 0.4rem;
  }

  .hud-quick-camera__btn--c1.is-active {
    min-width: 1.85rem;
    height: 1.85rem;
    padding-bottom: 0.1rem;
  }

  .hud-quick-camera__c1-mark {
    margin-top: 0.06rem;
    font-size: 0.55rem;
  }

  .hud-ride-map-controls {
    gap: 0.12rem;
  }

  .hud-ride-map-controls__style,
  .hud-ride-map-controls__zoom {
    min-width: 1.55rem;
    height: 1.55rem;
    padding: 0 0.22rem;
    border-radius: 0.4rem;
  }

  .hud-ride-map-controls__style {
    font-size: 0.65rem;
  }

  .hud-ride-map-controls__zoom {
    font-size: 0.85rem;
  }

  /*
   * 지시12-2: 좁은 폭에서 시각 버튼≪44px 이라 가로 ::after 가 이웃 중심을 덮음.
   * 스타일 칩과 같이 높만 44px — 배치(06-2) 유지, hit-test 는 본인 버튼.
   */
  .hud-quick-camera__btn::after,
  .hud-ride-map-controls__zoom::after {
    left: 0;
    right: 0;
    width: auto;
    height: max(100%, 44px);
    transform: translateY(-50%);
  }

  .hud-account {
    gap: 0.3rem;
    padding: 0 0.45rem 0 0.28rem;
    max-width: 7.2rem;
  }

  .hud-account__name {
    font-size: 0.72rem;
  }

  .hud-account__mileage {
    font-size: 0.6rem;
  }
}

