}

/* R1 칩도 알약을 버리고 파랑 글자만 남는다 — 같은 줄에서 배경 하나만 남으면 더 튄다. */
.hud-coach__r {
  font-weight: 700;
  font-size: 0.7rem;
  color: #2563EB;
  flex: 0 0 auto;
}

