  touch-action: manipulation;
}

/* 우상단 한 줄 — Outdoors/Satellite 토글, 줌 + − (지시66). 맵 뷰 시트와 동일 상태 */
.hud-ride-map-controls {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 0.2rem;
  flex-shrink: 0;
  pointer-events: auto !important;
  touch-action: manipulation;
}

.hud-ride-map-controls__style,
.hud-ride-map-controls__zoom {
  box-sizing: border-box;
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  /*
   * 크기는 퀵 카메라 버튼과 같다(2026-10-06 Chief: 기기마다 카메라 버튼과 동일하게).
   * 지시66: 기본 2.325rem × 1.2 = 2.79rem. transform 없이 layout 크기.
   * 터치 44px 는 실높이 대신 ::after 로 — 카메라 버튼과 같은 방식.
   */
  height: 2.79rem;
  min-width: 2.79rem;
  margin: 0;
  border: 1px solid #CBD5E1;
  border-radius: 0.525rem;
  background: #FFFFFF;
  color: #475569;
  font-weight: 600;
  line-height: 1;
  cursor: pointer;
  pointer-events: auto !important;
  touch-action: manipulation;
}

/* 줌 ± 는 정사각에 가깝다 — 세로·가로 모두 44px 히트(이웃과 겹치면 같은 그룹) */
.hud-ride-map-controls__zoom::after {
  content: "";
  position: absolute;
  top: 50%;
  left: 50%;
  width: max(100%, 44px);
  height: max(100%, 44px);
  transform: translate(-50%, -50%);
}

/* 스타일 칩은 가로가 이미 44+ — 높이만 확장 */
.hud-ride-map-controls__style::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  top: 50%;
  height: max(100%, 44px);
  transform: translateY(-50%);
}

.hud-quick-camera__btn::after {
  content: "";
  position: absolute;
  top: 50%;
  left: 50%;
  width: max(100%, 44px);
  height: max(100%, 44px);
  transform: translate(-50%, -50%);
}

.hud-ride-map-controls__style {
  /* 지시66: 좌우 padding 0.42rem × 1.2 = 0.504rem */
  padding: 0 0.504rem;
  font-size: 0.78rem;
  letter-spacing: 0.01em;
}

.hud-ride-map-controls__zoom {
  /* 지시66: 좌우 padding 0.42rem × 1.2 = 0.504rem */
  padding: 0 0.504rem;
  font-size: 1.08rem;
}

.hud-ride-map-controls__zoom:disabled {
  opacity: 0.38;
  cursor: default;
}

.hud-ride-map-controls__style:focus-visible,
.hud-ride-map-controls__zoom:focus-visible {
  outline: 2px solid #2563EB;
  outline-offset: 1px;
}

.hud-quick-camera__btn {
  box-sizing: border-box;
  position: relative;
  display: inline-flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  /* 지시66: 2.325rem × 1.2 = 2.79rem, 좌우 padding 0.42rem × 1.2 = 0.504rem (layout) */
  min-width: 2.79rem;
  height: 2.79rem;
  padding: 0 0.504rem;
  margin: 0;
  border: 1px solid #CBD5E1;
  border-radius: 0.525rem;
  background: #FFFFFF;
  color: #475569;
  font-size: 1.08rem;
  font-weight: 600;
  line-height: 1;
  cursor: pointer;
  pointer-events: auto !important;
  touch-action: manipulation;
}

.hud-quick-camera__btn--c1.is-active {
  /* 지시66: 2.775rem × 1.2 = 3.33rem (layout). padding-bottom 불변 */
  min-width: 3.33rem;
  height: 3.33rem;
  padding-bottom: 0.18rem;
}

.hud-quick-camera__num {
  line-height: 1;
}

.hud-quick-camera__c1-mark {
  margin-top: 0.12rem;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.02em;
  color: #2563EB;
  line-height: 1;
}

.hud-quick-camera__btn.is-active {
  border-color: #2563EB;
  background: #2563EB;
  color: #FFFFFF;
}

.hud-quick-camera__btn:focus-visible {
  outline: 2px solid #2563EB;
  outline-offset: 1px;
}

@media (max-height: 420px) {
  .hud-quick-camera__btn {
    /* 지시66: 2.025rem × 1.2 = 2.43rem (layout) */
    min-width: 2.43rem;
    height: 2.43rem;
    font-size: 0.975rem;
  }

  .hud-quick-camera__btn--c1.is-active {
    /* 1.55rem → 150% */
    min-width: 2.325rem;
    height: 2.325rem;
  }

  .hud-quick-camera__c1-mark {
    font-size: 0.63rem;
  }

  .hud-ride-map-controls__style,
  .hud-ride-map-controls__zoom {
    min-width: 2.025rem;
    height: 2.025rem;
  }

  .hud-ride-map-controls__zoom {
    font-size: 0.975rem;
  }
}

/*
 * 지시 06-2 — 폰 가로+좁은 폭에서 우상단 [QC][야외−+][계정] 이 좌상단 계기판(새 도로)을 덮는다.
 * 해법 a: 한 줄 유지, 카메라·맵 버튼의 시각 폭만 축소. 터치 44px 는 ::after.
 */
@media (max-width: 900px) and (max-height: 560px) {
  .map-hud__tr {
    gap: 0.2rem;
  }

  .hud-quick-camera {
    gap: 0.1rem;
  }

  .hud-quick-camera__btn {
    min-width: 1.55rem;
    height: 1.55rem;
    padding: 0 0.22rem;
    font-size: 0.85rem;
    border-radius: 0.4rem;
  }

  .hud-quick-camera__btn--c1.is-active {
    min-width: 1.85rem;
    height: 1.85rem;
    padding-bottom: 0.1rem;
  }

  .hud-quick-camera__c1-mark {
    margin-top: 0.06rem;
    font-size: 0.55rem;
  }

  .hud-ride-map-controls {
    gap: 0.12rem;
  }

  .hud-ride-map-controls__style,
  .hud-ride-map-controls__zoom {
    min-width: 1.55rem;
    height: 1.55rem;
    padding: 0 0.22rem;
    border-radius: 0.4rem;
  }

  .hud-ride-map-controls__style {
    font-size: 0.65rem;
  }

  .hud-ride-map-controls__zoom {
    font-size: 0.85rem;
  }

  /*
   * 지시12-2: 좁은 폭에서 시각 버튼≪44px 이라 가로 ::after 가 이웃 중심을 덮음.
   * 스타일 칩과 같이 높만 44px — 배치(06-2) 유지, hit-test 는 본인 버튼.
   */
  .hud-quick-camera__btn::after,
  .hud-ride-map-controls__zoom::after {
    left: 0;
    right: 0;
    width: auto;
    height: max(100%, 44px);
    transform: translateY(-50%);
  }

  .hud-account {
    gap: 0.3rem;
    padding: 0 0.45rem 0 0.28rem;
    max-width: 7.2rem;
  }

  .hud-account__name {
    font-size: 0.72rem;
  }

  .hud-account__mileage {
    font-size: 0.6rem;
  }
}

