.hud-action__row {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.35rem;
  flex-wrap: wrap;
}

.hud-action__btn {
  appearance: none;
  border: 1px solid #CBD5E1;
  background: #F1F5F9;
  color: #475569;
  font: inherit;
  font-size: 0.78rem;
  font-weight: 600;
  letter-spacing: 0.02em;
  padding: 0.45rem 0.85rem;
  border-radius: 999px;
