/* ---------- BR: 큰 메인 FAB ---------- */
.hud-main-fab {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: var(--hud-main-fab-size);
  height: var(--hud-main-fab-size);
  border-radius: 50%;
  border: 1.5px solid rgba(255, 255, 255, 0.35);
  background: #2563EB;
  color: #FFFFFF;
  font-size: 1.55rem;
  font-weight: 700;
  cursor: pointer;
  box-shadow: 0 10px 28px rgba(0, 0, 0, 0.32);
