.hud-icon-btn:hover {
  background: #EFF6FF;
  border-color: #2563EB;
}

.hud-icon-btn:focus-visible {
  outline: 2px solid #2563EB;
  outline-offset: 2px;
}

.hud-icon-btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.hud-icon-btn--lg {
  width: 3rem;
  height: 3rem;
  font-size: 1.2rem;
}

.hud-icon-btn--xl {
  width: 3.6rem;
  height: 3.6rem;
